#include <cstdio>

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    int nn = n;
    long long ex = 1;

    while (n % 10 == 0) {
        n /= 10;
        k--;
    }
    while (k > 0) {
        if (n % 2 == 0) {
            ex *= 5;
            n /= 2;
            k--;
        } else if (n % 5 == 0) {
            ex *= 2;
            n /= 5;
            k--;
        } else {
            break;
        }
    }
    while (k > 0) {
        ex *= 10;
        k--;
    }

    printf("%lld\n", ex * nn);
    return 0;
}

